INSERT IGNORE INTO `settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('billing','{\"legalName\":\"Alfa Solution\",\"gstin\":\"\",\"address\":\"India\",\"email\":\"nishant@alfasolution.net\",\"phone\":\"+91 9315424622\",\"taxRate\":18,\"taxLabel\":\"GST\",\"sacCode\":\"998314\",\"invoicePrefix\":\"ALFA\",\"paymentTermsDays\":7,\"invoiceNotes\":\"Thank you for your business. Payments are non-refundable once work on the corresponding milestone has started.\",\"bankDetails\":\"\"}','2026-11-26 03:20:40');
INSERT IGNORE INTO `settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('site.about','{\"headline\":\"A small studio that works like an in-house product team.\",\"intro\":\"Alfa Solution brings strategy, design and engineering together for businesses that need their digital presence to perform — not just exist.\",\"storyTitle\":\"Built around ideas. Driven by purpose.\",\"story\":\"Every business has a story worth telling and an opportunity worth exploring. We started Alfa Solution to give growing businesses the kind of digital team that larger companies take for granted: people who understand the business problem, design a clear solution, and engineer it properly.\\n\\nWe believe digital work should do more than look good. It should solve real problems, make things easier for people and support the way a business grows.\",\"values\":[{\"title\":\"Purpose first\",\"description\":\"Every decision starts with understanding the real purpose behind a project and the value it should create.\"},{\"title\":\"Thoughtful design\",\"description\":\"Great design is more than appearance. It should feel intuitive, useful and effortless to experience.\"},{\"title\":\"Quality always\",\"description\":\"From the smallest detail to the final delivery, we focus on reliable, carefully crafted solutions.\"},{\"title\":\"Grow together\",\"description\":\"Clear communication and lasting relationships built around shared goals.\"}],\"images\":[\"/about/about-team.jpeg\",\"/about/about-workspace.jpeg\",\"/about/about-design.jpeg\"]}','2026-11-26 03:20:40');
INSERT IGNORE INTO `settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('site.banner','{\"enabled\":false,\"message\":\"Now booking projects for the next quarter.\",\"linkLabel\":\"Plan your project\",\"linkHref\":\"/contact\"}','2026-11-26 03:20:40');
INSERT IGNORE INTO `settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('site.general','{\"companyName\":\"Alfa Solution\",\"tagline\":\"Websites, web apps and mobile products for growing businesses.\",\"email\":\"nishant@alfasolution.net\",\"phone\":\"+91 9315424622\",\"whatsapp\":\"919315424622\",\"address\":\"India\",\"hours\":\"Mon–Sat, 10:00–19:00 IST\",\"socials\":[{\"label\":\"LinkedIn\",\"href\":\"\"},{\"label\":\"Instagram\",\"href\":\"\"},{\"label\":\"GitHub\",\"href\":\"https://github.com/sumit9354800\"}]}','2026-11-26 03:20:40');
INSERT IGNORE INTO `settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('site.home','{\"heroHeadline\":\"We design and build websites that run real businesses.\",\"heroSubheadline\":\"Alfa Solution is a design and engineering studio from India. We plan, design, build and maintain websites, web applications and mobile apps — and the systems behind them.\",\"heroPrimaryLabel\":\"Start a project\",\"heroPrimaryHref\":\"/contact\",\"heroSecondaryLabel\":\"See live work\",\"heroSecondaryHref\":\"/work\",\"stats\":[{\"value\":\"3+\",\"label\":\"Years building for clients\"},{\"value\":\"30+\",\"label\":\"Projects delivered\"},{\"value\":\"30+\",\"label\":\"Businesses served\"},{\"value\":\"98\",\"label\":\"Lighthouse performance target\"}],\"introTitle\":\"Most business websites look fine and do nothing.\",\"introBody\":\"They load slowly, can\'t be updated without a developer, and don\'t turn visitors into enquiries. We start from what the website has to do for your business — then design and engineer every page, form and admin screen around that.\",\"process\":[{\"title\":\"Discover\",\"description\":\"We learn your business, audience and goals, and agree on what success looks like.\"},{\"title\":\"Define\",\"description\":\"Sitemap, features, content plan and a fixed scope with a clear timeline and price.\"},{\"title\":\"Design\",\"description\":\"Interface design for every key screen, reviewed with you on real devices.\"},{\"title\":\"Develop\",\"description\":\"Production code, CMS, integrations and testing across browsers and devices.\"},{\"title\":\"Launch & support\",\"description\":\"Deployment, analytics, search setup and ongoing maintenance after go-live.\"}],\"ctaTitle\":\"Have a project in mind?\",\"ctaBody\":\"Tell us what you need. We reply within one working day with next steps and a rough estimate.\",\"ctaLabel\":\"Start a project\",\"ctaHref\":\"/contact\"}','2026-11-26 03:20:40');
INSERT IGNORE INTO `settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('site.legal','{\"privacyHtml\":\"<h2>Who we are</h2><p>This website is operated by Alfa Solution (\\\"we\\\", \\\"us\\\"). This policy explains what personal information we collect through alfasolution.net, why we collect it and how we protect it.</p>\\n<h2>Information we collect</h2><ul><li><strong>Enquiries:</strong> your name, email, phone number, company and project details when you use our contact or enquiry forms.</li><li><strong>Job applications:</strong> your name, contact details, links, CV/resume and any information you choose to include.</li><li><strong>Payments:</strong> billing name, email, phone, address and GSTIN. Card, UPI and bank details are entered directly with our payment partner, Razorpay, and are never stored on our servers.</li><li><strong>Technical data:</strong> IP address, browser type and pages visited, used for security, spam prevention and analytics.</li></ul>\\n<h2>How we use it</h2><p>We use your information to respond to enquiries, deliver and invoice our services, assess job applications, prevent fraud and abuse, and improve this website. We do not sell your personal information.</p>\\n<h2>Sharing</h2><p>We share data only with service providers that help us run our business — hosting, email delivery, analytics and payment processing — and only as needed for those services, or when required by law.</p>\\n<h2>Retention</h2><p>Enquiries and client records are kept for as long as needed for the business relationship and legal, tax and accounting obligations. Job applications are kept for up to 12 months unless you ask us to delete them sooner.</p>\\n<h2>Your choices</h2><p>You can ask us to access, correct or delete your personal information by emailing us. We will respond within a reasonable time.</p>\\n<h2>Security</h2><p>Access to our admin systems is restricted, passwords are hashed, and data is transmitted over encrypted connections.</p>\\n<h2>Contact</h2><p>Questions about this policy can be sent to nishant@alfasolution.net.</p>\",\"termsHtml\":\"<h2>Agreement</h2><p>By using this website or engaging Alfa Solution for services, you agree to these terms. A signed proposal or statement of work takes precedence over these terms where they differ.</p>\\n<h2>Services and scope</h2><p>Each project\'s scope, deliverables, timeline and price are agreed in writing before work begins. Work outside the agreed scope is quoted separately.</p>\\n<h2>Payments</h2><ul><li>Projects typically require an advance payment before work starts, with the remaining balance on the milestones in your proposal.</li><li>Online payments are processed securely by Razorpay. An invoice is issued automatically for every successful payment.</li><li>Prices are in Indian Rupees and exclude applicable taxes unless stated otherwise.</li><li>Advance payments are non-refundable once work on the corresponding milestone has started.</li></ul>\\n<h2>Client responsibilities</h2><p>You are responsible for providing content, approvals and access needed for the project on time, and for ensuring you have the rights to any material you supply.</p>\\n<h2>Intellectual property</h2><p>On full payment, ownership of the final deliverables created specifically for you transfers to you. We may retain rights to pre-existing tools, libraries and know-how, and may show the completed work in our portfolio unless agreed otherwise.</p>\\n<h2>Third-party services</h2><p>Hosting, domains, plugins and other third-party services are subject to their providers\' terms and pricing.</p>\\n<h2>Limitation of liability</h2><p>To the extent permitted by law, our total liability for any claim relating to a project is limited to the amount paid for that project.</p>\\n<h2>Governing law</h2><p>These terms are governed by the laws of India.</p>\\n<h2>Contact</h2><p>Questions about these terms can be sent to nishant@alfasolution.net.</p>\",\"updatedAt\":\"2026-11-26\"}','2026-11-26 03:20:40');
INSERT IGNORE INTO `settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('site.navigation','{\"header\":[{\"label\":\"Services\",\"href\":\"/services\"},{\"label\":\"Work\",\"href\":\"/work\"},{\"label\":\"About\",\"href\":\"/about\"},{\"label\":\"Pricing\",\"href\":\"/pricing\"},{\"label\":\"Insights\",\"href\":\"/blog\"},{\"label\":\"Careers\",\"href\":\"/careers\"}],\"ctaLabel\":\"Start a project\",\"ctaHref\":\"/contact\",\"footerColumns\":[{\"title\":\"Studio\",\"links\":[{\"label\":\"About us\",\"href\":\"/about\"},{\"label\":\"Our team\",\"href\":\"/team\"},{\"label\":\"Careers\",\"href\":\"/careers\"},{\"label\":\"Contact\",\"href\":\"/contact\"}]},{\"title\":\"Work\",\"links\":[{\"label\":\"Portfolio\",\"href\":\"/work\"},{\"label\":\"Live previews\",\"href\":\"/work/live\"},{\"label\":\"Insights\",\"href\":\"/blog\"},{\"label\":\"Pricing\",\"href\":\"/pricing\"}]},{\"title\":\"Help\",\"links\":[{\"label\":\"FAQ\",\"href\":\"/faq\"},{\"label\":\"Privacy policy\",\"href\":\"/privacy-policy\"},{\"label\":\"Terms & conditions\",\"href\":\"/terms\"}]}],\"footerNote\":\"Design and engineering studio for websites, web applications and mobile apps.\"}','2026-11-26 03:20:40');
INSERT IGNORE INTO `settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('site.seo','{\"defaultTitle\":\"Alfa Solution | Website & App Development Company in India\",\"defaultDescription\":\"Alfa Solution designs and builds fast websites, web applications, B2B portals and mobile apps for growing businesses, with SEO and ongoing support.\",\"keywords\":[\"website development company\",\"web application development\",\"mobile app development\",\"B2B portal development\",\"SEO services India\",\"Best Website Design Company in India\"],\"ogImage\":\"/images/og-image.jpg\",\"pages\":[{\"page\":\"/about\",\"title\":\"About us\",\"description\":\"Meet Alfa Solution — a design and engineering studio for websites, web apps and mobile apps.\"},{\"page\":\"/services\",\"title\":\"Services\",\"description\":\"Website development, web applications, mobile apps, UI/UX, e-commerce and SEO from Alfa Solution.\"},{\"page\":\"/work\",\"title\":\"Our work\",\"description\":\"Live websites and applications designed and built by Alfa Solution.\"},{\"page\":\"/pricing\",\"title\":\"Pricing & packages\",\"description\":\"Transparent website and app development packages. Pay online securely.\"},{\"page\":\"/blog\",\"title\":\"Insights\",\"description\":\"Practical articles on websites, product design, development and growth.\"},{\"page\":\"/careers\",\"title\":\"Careers\",\"description\":\"Join Alfa Solution. See open roles in design, engineering and growth.\"},{\"page\":\"/contact\",\"title\":\"Contact\",\"description\":\"Start your project with Alfa Solution. We reply within one working day.\"},{\"page\":\"/team\",\"title\":\"Our team\",\"description\":\"The people behind Alfa Solution.\"},{\"page\":\"/faq\",\"title\":\"FAQ\",\"description\":\"Answers to common questions about working with Alfa Solution.\"}]}','2026-11-26 03:20:40');
INSERT IGNORE INTO `services` (`id`, `slug`, `title`, `short_description`, `description`, `image`, `features`, `deliverables`, `process_steps`, `technologies`, `starting_price`, `seo_title`, `seo_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (1,'website-development','Website development','Fast, responsive websites with a CMS your team can actually use — built to rank and convert.','<p>We build fast, responsive and scalable websites that help businesses establish a strong online presence. From company websites to content-heavy platforms, every build includes a CMS, analytics and the technical SEO foundations search engines expect.</p>','/service/web.jpeg','[\"Business websites\",\"Custom website development\",\"Content management (CMS)\",\"Responsive design\",\"Technical SEO setup\",\"Maintenance & support\"]','[\"Sitemap and content plan\",\"Responsive interface design\",\"Production website with CMS\",\"Analytics & Search Console setup\",\"Launch and handover session\"]','[{\"title\":\"Discovery\",\"description\":\"Goals, audience, competitors and the pages you need.\"},{\"title\":\"Design\",\"description\":\"Key screens designed and reviewed on desktop and mobile.\"},{\"title\":\"Build\",\"description\":\"Development, CMS setup and content entry.\"},{\"title\":\"Launch\",\"description\":\"Testing, deployment, analytics and search setup.\"}]','[\"Next.js\",\"React\",\"TypeScript\",\"Tailwind CSS\",\"MySQL\"]',NULL,NULL,NULL,1,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `services` (`id`, `slug`, `title`, `short_description`, `description`, `image`, `features`, `deliverables`, `process_steps`, `technologies`, `starting_price`, `seo_title`, `seo_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (2,'web-application-development','Web application development','Dashboards, portals and internal tools that replace spreadsheets and manual work.','<p>Custom web applications built around how your business actually operates — client portals, admin dashboards, booking systems and workflow tools with secure authentication and role-based access.</p>',NULL,'[\"Admin dashboards\",\"Client & partner portals\",\"Role-based access\",\"Payment integration\",\"Reports and exports\",\"API integrations\"]','[\"Technical specification\",\"UX flows and interface design\",\"Production application\",\"Admin panel\",\"Documentation\"]','[{\"title\":\"Specification\",\"description\":\"Users, roles, workflows and data model.\"},{\"title\":\"Prototype\",\"description\":\"Clickable flows for the critical journeys.\"},{\"title\":\"Build in sprints\",\"description\":\"Working software reviewed every one to two weeks.\"},{\"title\":\"Launch & iterate\",\"description\":\"Rollout, training and improvements from real use.\"}]','[\"Next.js\",\"Node.js\",\"TypeScript\",\"MySQL\",\"REST APIs\"]',NULL,NULL,NULL,2,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `services` (`id`, `slug`, `title`, `short_description`, `description`, `image`, `features`, `deliverables`, `process_steps`, `technologies`, `starting_price`, `seo_title`, `seo_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (3,'app-development','Mobile app development','Android and iOS apps with reliable backends, admin panels and push notifications.','<p>We develop user-focused mobile applications with reliable functionality, intuitive experiences and scalable architecture — helping businesses connect with customers and simplify everyday operations.</p>','/service/app.jpeg','[\"Android app development\",\"iOS app development\",\"Cross-platform apps\",\"Backend & admin panel\",\"API integration\",\"Store deployment support\"]','[\"App flows and interface design\",\"Android and/or iOS builds\",\"Backend and admin panel\",\"Store listing support\",\"Post-launch support\"]','[{\"title\":\"Product scope\",\"description\":\"Core features for the first release.\"},{\"title\":\"Design\",\"description\":\"Screens and interactions tested on devices.\"},{\"title\":\"Develop\",\"description\":\"App, backend and admin panel.\"},{\"title\":\"Release\",\"description\":\"Testing, store submission and monitoring.\"}]','[\"React Native\",\"Flutter\",\"Node.js\",\"REST APIs\"]',NULL,NULL,NULL,3,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `services` (`id`, `slug`, `title`, `short_description`, `description`, `image`, `features`, `deliverables`, `process_steps`, `technologies`, `starting_price`, `seo_title`, `seo_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (4,'ui-ux-design','UI/UX design','Interfaces that make products easier to use, understand and buy from.','<p>Thoughtful digital interfaces and user experiences — from research and information architecture to high-fidelity design systems your developers can build from.</p>','/about/about-design.jpeg','[\"User research\",\"Information architecture\",\"Wireframes & prototypes\",\"Interface design\",\"Design systems\",\"Usability reviews\"]','[\"User flows\",\"Wireframes\",\"High-fidelity screens\",\"Component library\",\"Developer handoff\"]','[{\"title\":\"Research\",\"description\":\"Users, goals and friction points.\"},{\"title\":\"Structure\",\"description\":\"Flows and wireframes.\"},{\"title\":\"Visual design\",\"description\":\"Screens and design system.\"},{\"title\":\"Validate\",\"description\":\"Prototype testing and refinement.\"}]','[\"Figma\",\"Design systems\",\"Prototyping\"]',NULL,NULL,NULL,4,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `services` (`id`, `slug`, `title`, `short_description`, `description`, `image`, `features`, `deliverables`, `process_steps`, `technologies`, `starting_price`, `seo_title`, `seo_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (5,'ecommerce-development','E-commerce development','Online stores with smooth checkout, payment gateways and easy product management.','<p>Flexible online stores designed to create smooth shopping experiences and simplify the buying journey, with product and order management your team can run day to day.</p>',NULL,'[\"Product & category management\",\"Cart and checkout\",\"Payment gateway integration\",\"Order management\",\"Shipping & tax setup\",\"Performance optimisation\"]','[\"Store design\",\"Product catalogue setup\",\"Payments and checkout\",\"Order admin\",\"Launch support\"]','[{\"title\":\"Catalogue\",\"description\":\"Products, variants and pricing rules.\"},{\"title\":\"Design\",\"description\":\"Store, product and checkout pages.\"},{\"title\":\"Build\",\"description\":\"Store, payments and order flows.\"},{\"title\":\"Launch\",\"description\":\"Testing real orders end to end.\"}]','[\"Next.js\",\"Razorpay\",\"MySQL\"]',NULL,NULL,NULL,5,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `services` (`id`, `slug`, `title`, `short_description`, `description`, `image`, `features`, `deliverables`, `process_steps`, `technologies`, `starting_price`, `seo_title`, `seo_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (6,'seo-digital-growth','SEO & digital growth','Technical SEO, content and analytics that bring in qualified enquiries.','<p>Search engine optimisation and growth support — technical audits, on-page optimisation, local SEO, content planning and reporting tied to enquiries, not vanity metrics.</p>',NULL,'[\"Technical SEO audits\",\"On-page optimisation\",\"Local SEO\",\"Content strategy\",\"Analytics & reporting\",\"Core Web Vitals\"]','[\"SEO audit report\",\"Fix list and implementation\",\"Keyword and content plan\",\"Monthly reporting\"]','[{\"title\":\"Audit\",\"description\":\"Technical, content and competitor review.\"},{\"title\":\"Fix\",\"description\":\"Speed, structure and on-page issues.\"},{\"title\":\"Grow\",\"description\":\"Content and local presence.\"},{\"title\":\"Report\",\"description\":\"Monthly results and next actions.\"}]','[\"Google Search Console\",\"Google Analytics\",\"Schema markup\"]',NULL,NULL,NULL,6,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `portfolio_projects` (`id`, `slug`, `title`, `client_name`, `category`, `project_type`, `service_id`, `year`, `role`, `summary`, `challenge`, `solution`, `results`, `technologies`, `features`, `cover_image`, `live_url`, `repo_url`, `embed_mode`, `embed_status`, `embed_checked_at`, `is_featured`, `is_published`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (1,'fostiima-business-school','FOSTIIMA Business School','FOSTIIMA Business School','Institutional website','client',1,2026,'Full-stack design & development','A modern institutional website for FOSTIIMA Business School covering programmes, admissions, placements, campus life, events, faculty and blogs — all managed from a custom CMS.','Migrating and restructuring a large legacy institutional website into a modern Next.js architecture while preserving existing content, SEO-friendly URLs, media assets and legacy campaign links.','A component-driven Next.js architecture with reusable sections, Prisma and MySQL for dynamic content, Cloudinary media management, structured blog content and admin workflows for every content type.','Legacy URLs preserved, content editable by the school\'s own team, and a responsive experience across devices.','[\"Next.js\",\"React\",\"TypeScript\",\"Tailwind CSS\",\"Prisma\",\"MySQL\",\"Cloudinary\"]','[\"Dynamic academic programmes\",\"Admissions sections\",\"Placement & recruiter showcase\",\"Faculty & campus information\",\"Blog & content management\",\"Legacy URL & SEO migration\"]','https://res.cloudinary.com/njq5pi5g/image/upload/v1790754959/Screenshot_2026-09-30_at_1.24.47_PM.png','https://fostiima.org/','https://github.com/sumit9354800/fostiima','auto','unknown',NULL,1,1,1,NULL,NULL,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `portfolio_projects` (`id`, `slug`, `title`, `client_name`, `category`, `project_type`, `service_id`, `year`, `role`, `summary`, `challenge`, `solution`, `results`, `technologies`, `features`, `cover_image`, `live_url`, `repo_url`, `embed_mode`, `embed_status`, `embed_checked_at`, `is_featured`, `is_published`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (2,'mrtechycool','MRTECHYCOOL','MRTECHYCOOL','Business website','client',1,2026,'Lead full-stack development','A commercial platform for MRTECHYCOOL with digital service booking, a lead-generation pipeline and technical service catalogues with sub-second load times.','Reaching a sub-1.2s LCP on mobile while integrating real-time enquiry booking with automated dispatch.','Server components with incremental revalidation, a lightweight SVG asset pipeline and streamlined API routes with server-side validation.','Core Web Vitals scores of 98+ and a booking flow that routes enquiries automatically.','[\"Next.js\",\"React\",\"Tailwind CSS\",\"Node.js\",\"MongoDB\",\"Express.js\"]','[\"Automated lead booking\",\"Dynamic service catalogue\",\"Admin analytics dashboard\",\"SEO & Core Web Vitals 98+\"]','https://res.cloudinary.com/njq5pi5g/image/upload/v1788944433/techcool.png','https://www.mrtechycool.in/','https://github.com/sumit9354800/techcool','auto','unknown',NULL,1,1,2,NULL,NULL,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `portfolio_projects` (`id`, `slug`, `title`, `client_name`, `category`, `project_type`, `service_id`, `year`, `role`, `summary`, `challenge`, `solution`, `results`, `technologies`, `features`, `cover_image`, `live_url`, `repo_url`, `embed_mode`, `embed_status`, `embed_checked_at`, `is_featured`, `is_published`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (3,'growje','Growje','Growje','Corporate portal','client',1,2024,'Full-stack web development','A high-conversion corporate portal for Growje supporting enterprise business solutions, client onboarding and digital marketing consulting.','A responsive, high-performance portal with zero layout shift and custom interactive enquiry funnels.','Modular components, validated contact pathways with Zod and aggressive asset caching.','A consistent experience from 360px to 1920px with a guided onboarding funnel.','[\"React\",\"TypeScript\",\"Tailwind CSS\",\"Node.js\",\"MongoDB\",\"REST APIs\"]','[\"Client onboarding funnel\",\"Responsive 360–1920px layouts\",\"Secure consultation booking\"]','https://res.cloudinary.com/njq5pi5g/image/upload/v1788944324/growje.png','https://growje.com/','https://github.com/sumit9354800/growje','auto','unknown',NULL,1,1,3,NULL,NULL,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `portfolio_projects` (`id`, `slug`, `title`, `client_name`, `category`, `project_type`, `service_id`, `year`, `role`, `summary`, `challenge`, `solution`, `results`, `technologies`, `features`, `cover_image`, `live_url`, `repo_url`, `embed_mode`, `embed_status`, `embed_checked_at`, `is_featured`, `is_published`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (4,'india-travel-safari-goa','India Travel Safari — Goa holidays','India Travel Safari','Campaign landing page','client',1,2026,'Frontend engineering','A conversion-focused Goa holiday landing page with a cinematic hero, day-wise itinerary, package comparison, inclusions, FAQs and WhatsApp and call CTAs.','Balancing strong visual storytelling, detailed itinerary information, pricing and lead-generation CTAs without overcrowding the page.','A structured mobile-first layout with itinerary cards, package highlighting, reusable CTA components and direct WhatsApp and phone conversion paths.','A single focused page that carries visitors from inspiration to enquiry.','[\"Next.js\",\"React\",\"TypeScript\",\"Tailwind CSS\"]','[\"Day-wise itinerary\",\"Premium vs standard comparison\",\"WhatsApp lead CTA\",\"Click-to-call\",\"FAQ section\",\"Google Tag Manager\"]','https://res.cloudinary.com/njq5pi5g/image/upload/v1791392566/Screenshot_2026-10-07_at_10.30.43_PM.png','https://travel.indiatravelsafari.com/','https://github.com/sumit9354800/goa-holiday','auto','unknown',NULL,1,1,4,NULL,NULL,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `portfolio_projects` (`id`, `slug`, `title`, `client_name`, `category`, `project_type`, `service_id`, `year`, `role`, `summary`, `challenge`, `solution`, `results`, `technologies`, `features`, `cover_image`, `live_url`, `repo_url`, `embed_mode`, `embed_status`, `embed_checked_at`, `is_featured`, `is_published`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (5,'mx-sammy-crm','MX SAMMY — B2B revenue CRM',NULL,'SaaS dashboard','independent',2,2024,'Full-stack development','An enterprise B2B sales and revenue analytics CRM with real-time revenue tracking, conversion pipelines, customer lifetime metrics and interactive dashboards.','Aggregating multi-source revenue streams into sub-second interactive analytics without client-side lag.','Memoised aggregation pipelines, modular dashboard cards and optimised client state.','Smooth, interactive dashboards on large datasets.','[\"Next.js\",\"React\",\"TypeScript\",\"Tailwind CSS\",\"Recharts\",\"Node.js\",\"MongoDB\"]','[\"Revenue telemetry\",\"Lead conversion pipelines\",\"Financial charts\",\"Customer lifetime analytics\"]','https://res.cloudinary.com/njq5pi5g/image/upload/v1789039538/dashbord.png','https://dashboard-chi-inky-30.vercel.app/','https://github.com/sumit9354800/dashboard','auto','unknown',NULL,0,1,5,NULL,NULL,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `portfolio_projects` (`id`, `slug`, `title`, `client_name`, `category`, `project_type`, `service_id`, `year`, `role`, `summary`, `challenge`, `solution`, `results`, `technologies`, `features`, `cover_image`, `live_url`, `repo_url`, `embed_mode`, `embed_status`, `embed_checked_at`, `is_featured`, `is_published`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (6,'stacked-3d','STACKED — 3D web experience',NULL,'Creative 3D web','independent',1,2024,'Creative frontend engineering','An interactive 3D web experiment exploring burger model choreography, lighting and real-time pointer physics.','Holding 60 FPS on low-power phones while computing dynamic transforms and lighting passes.','Instanced geometry, memory pooling, throttled pointer listeners and memoised WebGL state.','Smooth 3D interaction on mid-range mobile devices.','[\"Three.js\",\"React\",\"GSAP\",\"Tailwind CSS\",\"TypeScript\"]','[\"Custom shader lighting\",\"Spatial camera controls\",\"Procedural stacking\",\"Touch & pointer physics\"]','https://res.cloudinary.com/njq5pi5g/image/upload/v1788944464/burger-web.png','https://3-d-model-website-phi.vercel.app/','https://github.com/sumit9354800/3D-model-website','auto','unknown',NULL,0,1,6,NULL,NULL,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `portfolio_projects` (`id`, `slug`, `title`, `client_name`, `category`, `project_type`, `service_id`, `year`, `role`, `summary`, `challenge`, `solution`, `results`, `technologies`, `features`, `cover_image`, `live_url`, `repo_url`, `embed_mode`, `embed_status`, `embed_checked_at`, `is_featured`, `is_published`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (7,'kiranago','KiranaGo — grocery ordering',NULL,'Web application','independent',5,2023,'Full-stack development','A hyperlocal grocery discovery and ordering platform connecting neighbourhood stores, catalogues and one-tap checkout.','An ordering flow that works for users with very different levels of digital confidence.','High-contrast item tags and a streamlined one-tap checkout.','A simple path from search to order on any phone.','[\"React\",\"Node.js\",\"Express.js\",\"MongoDB\",\"Tailwind CSS\"]','[\"Local store search\",\"Quick-add catalogue\",\"Order estimator\",\"Mobile-first layout\"]','https://res.cloudinary.com/njq5pi5g/image/upload/v1788944354/kirana.png','https://kirana-go-tau.vercel.app/','https://github.com/sumit9354800/kirana-go','auto','unknown',NULL,0,1,7,NULL,NULL,'2026-11-26 03:20:40','2026-11-26 03:20:40');
