INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (1,'What services does Alfa Solution offer?','Website design and development, web applications, mobile apps, UI/UX design, e-commerce and SEO. We can take a project from first idea to launch and support it afterwards.','General',1,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (2,'How does a project work?','We start by understanding your goals and requirements, then agree a fixed scope, timeline and price. Design and development happen in reviewed stages, and we keep you involved until launch.','Process',2,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (3,'How long does a project take?','A standard business website usually takes 2–5 weeks. Web applications and mobile apps take longer depending on features. You get a timeline with your proposal.','Process',3,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (4,'Can you redesign my existing website?','Yes. We can redesign an existing site, improve its usability and speed, move it to a modern stack and add a CMS — while keeping your SEO and URLs intact.','General',4,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (5,'Will my website work on mobile?','Every site we build is responsive and tested on phones, tablets, laptops and large desktop screens.','General',5,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (6,'Do you provide support after launch?','Yes. Every package includes a support period, and we offer ongoing maintenance, updates and improvements after that.','Support',6,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (7,'How do payments work?','Most projects start with an advance (usually 40–50%) and the balance on delivery milestones. You can pay online by UPI, card or net banking through Razorpay, and you receive a GST invoice automatically.','Payments',7,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (8,'Is online payment secure?','Payments are processed by Razorpay. Your card or bank details are entered on Razorpay\'s secure checkout and never touch our servers. Every payment is verified on our server before it is marked as paid.','Payments',8,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (9,'How do I get started?','Send us a message through the contact page with a few lines about your business and what you need. We reply within one working day.','General',9,1,'2026-11-26 03:20:40','2026-11-26 03:20:40');
