INSERT IGNORE INTO `job_openings` (`id`, `slug`, `title`, `department`, `location`, `employment_type`, `work_mode`, `experience`, `salary_range`, `summary`, `description`, `responsibilities`, `requirements`, `status`, `closes_at`, `created_at`, `updated_at`) VALUES (1,'frontend-developer-nextjs','Frontend developer (Next.js)','Engineering','India','full_time','hybrid','1–3 years',NULL,'Build fast, accessible interfaces for client websites and web applications using Next.js, React and TypeScript.','<p>You\'ll work with our design and backend team to ship production websites and dashboards for clients across industries.</p>','[\"Build responsive interfaces from design files\",\"Write clean, typed React and Next.js code\",\"Optimise performance and Core Web Vitals\",\"Work with the backend team on APIs and data\"]','[\"Strong HTML, CSS and JavaScript fundamentals\",\"Experience with React and TypeScript\",\"Comfort with Tailwind CSS or similar\",\"A portfolio of live work\"]','draft',NULL,'2026-11-26 03:20:40','2026-11-26 03:20:40');
